package io.github.jesterportfolio.hearth.survival;

import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import io.github.jesterportfolio.hearth.survival.platform.*;
import io.github.jesterportfolio.hearth.economy.PlatformStore;

class ConfigurationRecoveryTest {
    @TempDir Path root;
    ConfigurationChanges changes()throws Exception{Files.writeString(root.resolve("platform.properties"),"old");Files.writeString(root.resolve("next.candidate"),"new");return new ConfigurationChanges(root);}
    ConfigurationChanges.Plan stage(ConfigurationChanges c)throws Exception{return c.stage("platform.properties","next.candidate",(n,a,b)->{});}
    PlatformStore.Config row(ConfigurationChanges.Plan p,String state){return new PlatformStore.Config(p.id(),p.name(),p.before(),p.after(),state);}
    @Test void directionIsPersistedBeforeDatabaseAndRollbackIsPendingUntilFinalized()throws Exception{var c=changes();var p=stage(c);c.begin(p,false,(n,a,b)->{});assertEquals("PREPARING",c.state(p));assertFalse(ConfigurationReview.read(c,List.of()).clear());c.publish(p,false,(n,a,b)->{});c.mark(p,"COMMITTED");c.begin(p,true,(n,a,b)->{});assertEquals("ROLLBACK_PREPARING",c.state(p));c.publish(p,true,(n,a,b)->{});var next=new ConfigurationChanges(root);assertEquals("ROLLBACK_APPLIED",next.state(next.plan(p.id())));assertFalse(ConfigurationReview.read(next,List.of(row(p,"PREPARED"))).clear());c.mark(p,"ROLLED_BACK");assertTrue(ConfigurationReview.read(c,List.of(row(p,"ROLLED_BACK"))).clear());}
    @Test void legacyRollbackWithUncommittedDatabaseIsNotMistakenForClean()throws Exception{var c=changes();var p=stage(c);c.mark(p,"ROLLED_BACK");var review=ConfigurationReview.read(c,List.of(row(p,"PREPARED")));assertFalse(review.clear());assertEquals("STATE_MISMATCH",review.entries().getFirst().problem());assertTrue(review.allows(p.id()));}
    @Test void missingEvidenceAndIdentityConflictCannotBeClearedByLocalTerminalMarker()throws Exception{var c=changes();var p=stage(c);c.mark(p,"COMMITTED");assertFalse(ConfigurationReview.read(c,List.of()).clear());var wrong=new PlatformStore.Config(p.id(),"rpg-policy.properties",p.before(),p.after(),"COMMITTED");assertEquals("IDENTITY_MISMATCH",ConfigurationReview.read(c,List.of(wrong)).entries().getFirst().problem());var absent=new PlatformStore.Config(UUID.randomUUID(),p.name(),p.before(),p.after(),"PREPARED");assertTrue(ConfigurationReview.read(c,List.of(absent)).entries().stream().anyMatch(e->e.problem().equals("EVIDENCE_MISSING")));}
    @Test void partialDirectoriesRemainInspectableAndBlockOtherChanges()throws Exception{var c=changes();var p=stage(c);Files.createDirectory(root.resolve("platform-changes").resolve(UUID.randomUUID().toString()));var review=ConfigurationReview.read(c,List.of());assertEquals(1,review.issues().size());assertEquals(1,review.entries().size());assertFalse(review.allows(p.id()));assertThrows(Exception.class,c::pending);}
    @Test void externalChangesAndChangedArchivesArePreserved()throws Exception{var c=changes();var p=stage(c);Files.writeString(root.resolve("platform.properties"),"external");assertEquals("EXTERNAL",c.inspect(p.id()).position());assertThrows(Exception.class,()->c.begin(p,false,(n,a,b)->{}));assertEquals("STAGED",c.state(p));assertEquals("external",Files.readString(root.resolve("platform.properties")));Files.writeString(p.directory().resolve("after"),"tamper");assertEquals(1,c.scan().issues().size());assertFalse(ConfigurationReview.read(c,List.of()).clear());}
    @Test void matchingInterruptedWriteCanResumeAndForeignWriteCannotBeOverwritten()throws Exception{var c=changes();var p=stage(c);Path temp=root.resolve("platform.properties.platform-writing");Files.writeString(temp,"foreign");assertThrows(Exception.class,()->c.publish(p,false,(n,a,b)->{}));assertEquals("old",Files.readString(root.resolve("platform.properties")));assertEquals("foreign",Files.readString(temp));Files.writeString(temp,"new");c.publish(p,false,(n,a,b)->{});assertEquals("new",Files.readString(root.resolve("platform.properties")));assertEquals("APPLIED",c.state(p));}
    @Test void onePendingChangeBlocksAnUnrelatedCandidate()throws Exception{var c=changes();var p=stage(c);var other=stage(c);c.begin(p,false,(n,a,b)->{});var review=ConfigurationReview.read(c,List.of(row(p,"PREPARED")));assertTrue(review.allows(p.id()));assertFalse(review.allows(other.id()));}
    @Test void terminalOlderChangesDoNotRequireRestoringHistoricalFiles()throws Exception{var c=changes();var p=stage(c);c.publish(p,false,(n,a,b)->{});c.mark(p,"COMMITTED");Files.writeString(root.resolve("next.candidate"),"latest");var next=stage(c);c.publish(next,false,(n,a,b)->{});c.mark(next,"COMMITTED");assertTrue(ConfigurationReview.read(c,List.of(row(p,"COMMITTED"),row(next,"COMMITTED"))).clear());assertEquals("EXTERNAL",c.inspect(p.id()).position());}
    @Test void previewIsBoundedAndStateAndRestartMetadataAreValidated()throws Exception{var c=changes();Files.writeString(root.resolve("next.candidate"),"x".repeat(500)+"\n"+"y\n".repeat(50));var p=stage(c);assertTrue(c.inspect(p.id()).preview().size()<=13);assertTrue(c.inspect(p.id()).preview().stream().allMatch(line->line.length()<=182));Path manifest=p.directory().resolve("manifest.properties");Files.writeString(manifest,Files.readString(manifest).replace("restart=false","restart=true"));assertThrows(Exception.class,()->c.plan(p.id()));}
    @Test void desiredFileStillRequiresValidationOnResume()throws Exception{var c=changes();var p=stage(c);c.publish(p,false,(n,a,b)->{});assertThrows(Exception.class,()->c.publish(p,false,(n,a,b)->{throw new IllegalArgumentException("new adapter rejects");}));assertEquals("new",Files.readString(root.resolve("platform.properties")));}
}
